import React from 'react';
import { EventServices, AttendeeServices } from '@/api';
import { EventCard } from '@/pages/events/EventCard';
import { EventResult } from '@/types/event.types';
import { RegisteredEventInfo } from '@/types/attendee.types';
import { CallStatus } from '@/types/api.types';
import { PageContainer } from '@/components/PageContainer';
import { PageMeta } from '@/components/PageMeta';
import { StatusMessage } from '@/components/StatusMessage';
import { Pathname } from '@/constants/Routes';
import { EnvConfig } from '@/constants/EnvConfig';
import { useNavigate } from '@tanstack/react-router';
import { IsTokenValid } from '@/utils/token';
import { markdownToPlainText, truncate } from '@/utils/seo';

interface EventViewPageProps {
    eventId?: string;
}

const EventViewPage: React.FC<EventViewPageProps> = ({ eventId: propEventId }) => {
    const navigate = useNavigate();
    const [event, setEvent] = React.useState<EventResult | null>(null);
    const [loading, setLoading] = React.useState<boolean>(true);
    const [error, setError] = React.useState<string | null>(null);
    const [registrationInfo, setRegistrationInfo] = React.useState<RegisteredEventInfo | null>(null);

    React.useEffect(() => {
        const eventId = propEventId;
        if (!eventId) {
            navigate({ to: Pathname.Events as string });
            return;
        }

        Promise.all([
            EventServices.GetEventById(eventId),
            IsTokenValid() ? AttendeeServices.GetMyRegistration(eventId).catch(() => null) : Promise.resolve(null)
        ]).then(([eventResponse, attendeeResponse]) => {
            if (eventResponse.data.status >= 200 && eventResponse.data.status < 300) {
                setEvent(eventResponse.data.result);
            } else {
                setError(`Event "${eventId}" not found.`);
            }
            if (attendeeResponse?.data?.result) {
                const a = attendeeResponse.data.result;
                setRegistrationInfo({
                    eventId: a.eventId,
                    foodPreference: a.foodPreference,
                    headCount: a.headCount,
                    donation: a.donation,
                    registeredAt: a.createdAt,
                });
            }
        }).catch(() => {
            setError(`Failed to load event "${eventId}".`);
        }).finally(() => {
            setLoading(false);
        });
    }, [propEventId, navigate]);

    const handleEventEdit = (eventId: string) => {
        navigate({ to: `${Pathname.Events_Edit}/${eventId}` as string });
    };

    const handleRegistrationChange = () => {        if (!event) return;
        if (!IsTokenValid()) return;
        AttendeeServices.GetMyRegistration(event.id.toString())
            .then(response => {
                if (response?.data?.result) {
                    const a = response.data.result;
                    setRegistrationInfo({
                        eventId: a.eventId,
                        foodPreference: a.foodPreference,
                        headCount: a.headCount,
                        donation: a.donation,
                        registeredAt: a.createdAt,
                    });
                } else {
                    setRegistrationInfo(null);
                }
            })
            .catch(() => setRegistrationInfo(null));
    };

    const seo = React.useMemo(() => {
        if (!event) return null;

        const start = new Date(event.startDateTime);
        const end = new Date(event.endDateTime);
        const when = start.toLocaleDateString('en-IN', { day: 'numeric', month: 'long', year: 'numeric' });
        // Lead with the facts a searcher scans for (date, place), then as much of the
        // organiser's own copy as fits the ~155 characters a result snippet shows.
        const where = event.isOnlineMeeting ? 'Online' : event.location;
        const summary = markdownToPlainText(event.details);
        const description = truncate([`${when} · ${where}.`, summary].filter(Boolean).join(' '));

        const structuredData = {
            '@context': 'https://schema.org',
            '@type': 'Event',
            name: event.title,
            description: summary || description,
            startDate: start.toISOString(),
            endDate: end.toISOString(),
            eventAttendanceMode: event.isOnlineMeeting
                ? 'https://schema.org/OnlineEventAttendanceMode'
                : 'https://schema.org/OfflineEventAttendanceMode',
            eventStatus: 'https://schema.org/EventScheduled',
            location: event.isOnlineMeeting
                ? { '@type': 'VirtualLocation', url: event.registrationLink || window.location.href }
                : { '@type': 'Place', name: event.location, address: event.location },
            organizer: { '@type': 'Organization', name: EnvConfig.SiteName, url: window.location.origin },
        };

        return {
            title: `${event.title} | ${EnvConfig.SiteName}`,
            description,
            path: `${Pathname.Events}/${event.id}`,
            structuredData,
        };
    }, [event]);

    if (loading) {
        return (
            <PageContainer>
                <StatusMessage currentStatus={CallStatus.InProgress} notStartedMessage="" correlationId="" />
            </PageContainer>
        );
    }

    if (!event) {
        return (
            <>
                {/* A missing event must not be indexed, and the generic site title would otherwise stand in. */}
                <PageMeta
                    title={`Event not found | ${EnvConfig.SiteName}`}
                    description={`This event is no longer available on ${EnvConfig.SiteName}.`}
                    noIndex
                    priority={10}
                />
                <PageContainer>
                    <p>{error || 'Event not found.'}</p>
                </PageContainer>
            </>
        );
    }

    return (
        <>
            {seo && (
                <PageMeta
                    title={seo.title}
                    description={seo.description}
                    path={seo.path}
                    type="article"
                    structuredData={seo.structuredData}
                    priority={10}
                />
            )}
            <PageContainer>
                <EventCard
                    event={event}
                    registrationInfo={registrationInfo}
                    onRegistrationChange={handleRegistrationChange}
                    onEventEdit={handleEventEdit}
                />
            </PageContainer>
        </>
    );
};

export default EventViewPage;
