/** Longest description search engines and social cards display before truncating. */
const MAX_DESCRIPTION_LENGTH = 155;

/**
 * Flattens markdown to plain prose for a `<meta name="description">`, which renders no markup.
 * Emphasis/heading/list markers and link syntax are stripped while the link text is kept.
 */
export const markdownToPlainText = (markdown?: string): string => {
    if (!markdown) return '';
    return markdown
        .replace(/```[\s\S]*?```/g, ' ')
        .replace(/`([^`]*)`/g, '$1')
        .replace(/!\[[^\]]*\]\([^)]*\)/g, ' ')
        .replace(/\[([^\]]*)\]\([^)]*\)/g, '$1')
        .replace(/^\s{0,3}>+\s?/gm, ' ')
        .replace(/^\s{0,3}#{1,6}\s*/gm, ' ')
        .replace(/^\s{0,3}(?:[-*+]|\d+\.)\s+/gm, ' ')
        .replace(/^\s{0,3}(?:[-*_]\s*){3,}$/gm, ' ')
        .replace(/[*_~]/g, '')
        .replace(/&nbsp;/gi, ' ')
        .replace(/\s+/g, ' ')
        .trim();
};

/** Truncates on a word boundary and appends an ellipsis, so descriptions never cut mid-word. */
export const truncate = (text: string, maxLength: number = MAX_DESCRIPTION_LENGTH): string => {
    if (text.length <= maxLength) return text;
    const clipped = text.slice(0, maxLength - 1);
    const lastSpace = clipped.lastIndexOf(' ');
    return `${(lastSpace > maxLength * 0.6 ? clipped.slice(0, lastSpace) : clipped).trimEnd()}…`;
};
